        sysm = pick(R, SYS_GENERAL)
        uu = u if rep == 0 else R.choice(["Hey, " + lf(u), "Random question: " + lf(u), lf(u) + " Just curious."])
        out.append(mk(CAT, "casual_chat", [("user", uu), ("assistant", a)], f"cc2_{i}", "easy", "authored" if rep == 0 else "composed", sysm))

