FOLLOW = ["Do you want to talk through it?", "Would practical ideas help, or would you rather just vent?", "What would be most useful right now?", "Do you want to tell me a bit more?", "How are you holding up?"]
for n in range(280):
    ev, feel, tip = R.choice(EV)
    f = R.choice(FEEL[feel])
    u = R.choice([f"{ev[0].upper() + ev[1:]}.", f"Honestly, {ev}.", f"So {ev}, and I'm feeling {feel}.", f"I need to vent: {ev}.", f"{ev[0].upper() + ev[1:]}. I don't know what to do."])
    a = f"{f} {tip} {R.choice(FOLLOW)}"
    out.append(mk(CAT, "empathy", [("user", u), ("assistant", a)], f"cc2e_{n}", "medium", "composed", pick(R, SYS_GENERAL)))

save("conversation2", out)
